public final class KasabaBattleRoyale extends JavaPlugin implements Listener,TabCompleter {
    enum Stage{BOS,BEKLIYOR,GERI_SAYIM,OYNANIYOR,BITIYOR}
    static final class Session {
        final UUID party;final List<UUID> members;Integer room;
        Session(UUID party,List<UUID> members){this.party=party;this.members=List.copyOf(members);}
    }
    static final class Room {
        final int id;Stage stage=Stage.BOS;Mode mode;int countdown,elapsed,ending;
        UUID epoch=UUID.randomUUID();final LinkedHashSet<UUID> players=new LinkedHashSet<>();
        final Map<UUID,Integer> teams=new HashMap<>(),kills=new HashMap<>();
        final Map<UUID,UUID> lastHit=new HashMap<>();final Map<UUID,Long> lastHitAt=new HashMap<>();
        final Map<String,LootInventory> chests=new LinkedHashMap<>();final Set<UUID> drops=new HashSet<>();
        Set<Integer> previousChests=new HashSet<>();Room(int id){this.id=id;}
    }
    static final class LootInventory implements InventoryHolder {
        final int room;final UUID epoch;final Location location;final boolean rare;final Inventory inventory;
        LootInventory(int room,UUID epoch,Location location,boolean rare){this.room=room;this.epoch=epoch;this.location=location.clone();this.rare=rare;inventory=Bukkit.createInventory(this,27,rare?"§5BR • Nadir Ganimet":"§6BR • Ganimet");}
        @Override public Inventory getInventory(){return inventory;}
    }
    private BattlePresentation presentation;private ArenaStore arenas;private BattleSnapshot snapshots;private LootTable loot;private HubApi hub;
    final Map<Integer,Room> rooms=new TreeMap<>();final Map<UUID,Session> sessions=new HashMap<>();
    private final Set<UUID> moving=new HashSet<>(),editing=new HashSet<>();
    private final Map<UUID,Location[]> selections=new HashMap<>();private final Map<UUID,Long> pages=new HashMap<>(),heals=new HashMap<>();
    private final Map<UUID,Long> warnings=new HashMap<>();private final Random random=new Random();private long sequence;
    private final Map<UUID,ReservePool> reserves=new HashMap<>();private final Set<UUID> pendingReserve=new HashSet<>();private final Map<UUID,ItemStack> landingArmor=new HashMap<>();
    private NamespacedKey wingKey;
    private NamespacedKey compassKey,healKey,reserveKey,itemKey;

    @Override public void onEnable(){
        saveDefaultConfig();if(getConfig().getInt("network-rules-version",0)<1){if(getConfig().getInt("alan-bekleme-saniye",180)==180)getConfig().set("alan-bekleme-saniye",120);if(getConfig().getInt("alan-daralma-saniye",600)==600)getConfig().set("alan-daralma-saniye",480);getConfig().set("sandik-asgari-mesafe",12);getConfig().set("network-rules-version",1);saveConfig();}wingKey=new NamespacedKey(this,"inis-kanadi");presentation=new BattlePresentation(this);compassKey=new NamespacedKey(this,"br-pusula");healKey=new NamespacedKey(this,"sifa");reserveKey=new NamespacedKey(this,"yedek-kalp");itemKey=new NamespacedKey(this,"mac-esyasi");
        try{java.nio.file.Path prepared=Bukkit.getWorldContainer().toPath().resolve("KasabaBR");if(Bukkit.getWorld("KasabaBR")==null&&java.nio.file.Files.isRegularFile(prepared.resolve("level.dat"))&&java.nio.file.Files.isRegularFile(prepared.resolve("kasaba-br-map.yml")))Bukkit.createWorld(new WorldCreator("KasabaBR"));arenas=new ArenaStore(getDataFolder().toPath());snapshots=new BattleSnapshot(getDataFolder().toPath().resolve("oyuncu-yedekleri"));loot=new LootTable(getDataFolder().toPath().resolve("ganimetler.yml"),healKey,reserveKey);for(int i=1;i<=3;i++)rooms.put(i,new Room(i));for(World world:Bukkit.getWorlds())if(arenas.importProfile(world))getLogger().info("Hazır harita tanındı: "+world.getName()+"; 3 arena, lobi ve güvenli sandık adayları kaydedildi.");}
        catch(Exception e){getLogger().log(Level.SEVERE,"BR verileri okunamadı; dosyalar korundu.",e);Bukkit.getPluginManager().disablePlugin(this);return;}
        try(var input=new java.io.InputStreamReader(Objects.requireNonNull(getResource("hazir-dis-sandiklar.yml")),java.nio.charset.StandardCharsets.UTF_8)){
            int added=arenas.expandPreparedCandidates(org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(input).getStringList("locations"),false);if(added>0)getLogger().info("Hazır haritaya "+added+" güvenli dış alan sandık adayı eklendi; lobi ve doğmalar korundu.");
        }catch(IOException e){getLogger().log(Level.SEVERE,"Ek dış alan noktaları kaydedilemedi; BR kapatılıyor.",e);Bukkit.getPluginManager().disablePlugin(this);return;}
        try(var input=new java.io.InputStreamReader(Objects.requireNonNull(getResource("hazir-yogun-sandiklar.yml")),java.nio.charset.StandardCharsets.UTF_8)){
            int added=arenas.expandPreparedCandidates(org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(input).getStringList("locations"),true);if(added>0)getLogger().info("Hazır haritaya "+added+" yoğun ganimet adayı eklendi; kayıtlı yerler korundu.");
        }catch(IOException e){getLogger().log(Level.SEVERE,"Yoğun ganimet noktaları kaydedilemedi; BR kapatılıyor.",e);Bukkit.getPluginManager().disablePlugin(this);return;}
        Objects.requireNonNull(getCommand("br")).setTabCompleter(this);Bukkit.getPluginManager().registerEvents(this,this);
        if(Bukkit.getPluginManager().isPluginEnabled("KasabaAuth"))Bukkit.getPluginManager().registerEvents(new BattleAuthBridge(this),this);
        if(Bukkit.getPluginManager().isPluginEnabled("KasabaHub")){hub=Bukkit.getServicesManager().load(HubApi.class);if(hub!=null)try{hub.register(this,new BattleGame());}catch(RuntimeException e){getLogger().log(Level.SEVERE,"Battle Royale oyun kaydı yapılamadı. Elle eklenmiş battle girişi varsa /oyunlar sil battle kullanıp yeniden başlat.",e);Bukkit.getPluginManager().disablePlugin(this);return;}}
        Bukkit.getScheduler().runTaskTimer(this,this::tick,20,20);Bukkit.getScheduler().runTaskTimer(this,this::tidyInventories,1,10);getLogger().info("Kasaba BR 1.1.0: üç maç, aralıklı ganimet, VIP yedek kalpleri, 9 yuva sınırı ve birleşen yedek kalpler.");
    }
    @Override public void onDisable(){
        if(hub!=null)try{hub.unregister(this,"battle");}catch(RuntimeException e){getLogger().warning(e.getMessage());}
        for(UUID id:new ArrayList<>(sessions.keySet())){Player p=Bukkit.getPlayer(id);if(p!=null){Location before=null;try{before=snapshots.location(p);}catch(IOException ignored){}cleanup(id);if(before!=null&&before.getWorld()!=null)teleport(p,before);}}
        for(Room r:rooms.values())clearWorld(r);
    }
    private final class BattleGame implements HubGame {
        public GameInfo info(){return new GameInfo("battle","Battle Royale","Solo / İkili / Dörtlü • 3 eşzamanlı maç • büyülü ganimet",1,4);}
        public boolean available(){return arenas.lobbyReady();}
        public boolean join(List<Player> team){return enter(team);}
        public boolean lobby(UUID id){Session session=sessions.get(id);Room r=session==null||session.room==null?null:rooms.get(session.room);return session!=null&&(r==null||r.stage==Stage.BEKLIYOR||r.stage==Stage.GERI_SAYIM);}
        public void leave(UUID id){cleanup(id);}
    }
    private boolean auth(Player p){if(!Bukkit.getPluginManager().isPluginEnabled("KasabaAuth"))return true;var service=Bukkit.getServicesManager().load(tr.kasaba.auth.api.AuthState.class);return service!=null&&service.authenticated(p.getUniqueId());}
    private void ready(Player p){if(!auth(p))throw new IllegalArgumentException("Önce giriş yap.");if(!p.hasPermission("br.kullan"))throw new IllegalArgumentException("BR yetkin yok.");}
    private void tell(CommandSender p,String text){p.sendMessage("§6[Kasaba BR] §r"+text);}
    private void warn(Player p,String text){long now=System.currentTimeMillis();if(now-warnings.getOrDefault(p.getUniqueId(),0L)>2000){warnings.put(p.getUniqueId(),now);tell(p,text);}}
    private boolean teleport(Player p,Location l){moving.add(p.getUniqueId());try{return p.teleport(l,PlayerTeleportEvent.TeleportCause.PLUGIN);}finally{moving.remove(p.getUniqueId());}}
    private boolean lobby(Location l){return ArenaStore.in(arenas.lobbyArea,l);}
    private ArenaStore.Definition definition(int id){ArenaStore.Definition d=arenas.rooms.get(id);if(d==null)throw new IllegalArgumentException("Arena numarası 1, 2 veya 3 olmalı.");return d;}
    private Room room(Player p){Session s=sessions.get(p.getUniqueId());return s==null||s.room==null?null:rooms.get(s.room);}
    private boolean alive(Player p){Room r=room(p);return r!=null&&r.stage==Stage.OYNANIYOR&&r.players.contains(p.getUniqueId());}
    private boolean protectedAt(Location l){if(lobby(l))return true;return arenas.rooms.values().stream().anyMatch(d->ArenaStore.in(d.area,l));}
    private boolean edit(Player p,Location l){if(!editing.contains(p.getUniqueId())||!p.hasPermission("br.admin"))return false;for(Room r:rooms.values())if(r.stage!=Stage.BOS&&ArenaStore.in(definition(r.id).area,l))return false;return true;}
    private void reset(Player p){presentation.clear(p);heals.remove(p.getUniqueId());p.closeInventory();p.setItemOnCursor(null);p.getInventory().clear();p.getInventory().setArmorContents(new ItemStack[4]);p.getInventory().setItemInOffHand(null);for(PotionEffect e:p.getActivePotionEffects())p.removePotionEffect(e.getType());p.setAbsorptionAmount(0);p.setInvulnerable(false);p.setFireTicks(0);p.setFallDistance(0);p.setGameMode(GameMode.SURVIVAL);p.setFlying(false);p.setAllowFlight(false);p.setTotalExperience(0);p.setLevel(0);p.setExp(0);p.setFoodLevel(20);p.setSaturation(8);p.setExhaustion(0);if(!p.isDead())p.setHealth(Math.min(20,p.getAttribute(Attribute.MAX_HEALTH).getValue()));}
    private void compass(Player p){if(!sessions.containsKey(p.getUniqueId())||alive(p))return;ItemStack item=new ItemStack(Material.COMPASS);var meta=item.getItemMeta();meta.setDisplayName("§6Battle Royale §7• Mod seç");meta.getPersistentDataContainer().set(compassKey,PersistentDataType.BYTE,(byte)1);item.setItemMeta(meta);p.getInventory().setItem(8,item);}
    private boolean marked(ItemStack i){return i!=null&&i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().has(compassKey);}
    private boolean enter(List<Player> team){
        if(team.isEmpty()||!arenas.lobbyReady())return false;UUID party=UUID.randomUUID();List<UUID> ids=team.stream().map(Player::getUniqueId).toList();Map<Player,Location> before=new LinkedHashMap<>();
        try{for(Player p:team){ready(p);if(sessions.containsKey(p.getUniqueId()))throw new IllegalArgumentException("Gruptaki oyuncu zaten BR'de.");if(snapshots.pending(p))snapshots.restore(p);snapshots.save(p);before.put(p,p.getLocation());sessions.put(p.getUniqueId(),new Session(party,ids));reset(p);if(!teleport(p,arenas.lobby))throw new IllegalArgumentException("BR lobisine ışınlanma engellendi.");compass(p);}for(Player p:team)Bukkit.getScheduler().runTaskLater(this,()->{Session pending=sessions.get(p.getUniqueId());if(p.isOnline()&&pending!=null&&pending.room==null&&lobby(p.getLocation()))menu(p);},2);return true;}
        catch(Exception e){for(var entry:before.entrySet()){cleanup(entry.getKey().getUniqueId());teleport(entry.getKey(),entry.getValue());}getLogger().log(Level.WARNING,"BR girişi geri alındı.",e);return false;}
    }
    private void joinGame(Player p){ready(p);if(sessions.containsKey(p.getUniqueId()))return;if(hub!=null){if(hub.playing(p.getUniqueId()))throw new IllegalArgumentException("Önce /lobi ile mevcut oyundan çık.");Bukkit.dispatchCommand(p,"oyunlar git battle");}else if(!enter(List.of(p)))throw new IllegalArgumentException("BR lobisi hazır değil; /br yardım kullan.");}
    private void cleanup(UUID id){
        reserves.remove(id);pendingReserve.remove(id);landingArmor.remove(id);
        Session s=sessions.remove(id);pages.remove(id);heals.remove(id);editing.remove(id);if(s!=null&&s.room!=null)removeFromRoom(id,rooms.get(s.room),false);
        Player p=Bukkit.getPlayer(id);if(p!=null&&presentation!=null)presentation.clear(p);if(p!=null&&snapshots!=null)try{snapshots.restore(p);}catch(IOException e){getLogger().log(Level.SEVERE,"BR normal envanter yedeği geri yüklenemedi: "+id,e);p.kick(Component.text("BR yedeğin korunuyor. Yöneticiye haber ver."));}
    }
    void recover(Player p){if(!p.isOnline()||!auth(p)||sessions.containsKey(p.getUniqueId()))return;presentation.clear(p);try{if(snapshots.pending(p)){snapshots.restore(p);tell(p,"Önceki BR oturumundan normal eşyaların ve modun geri yüklendi.");}}catch(IOException e){getLogger().log(Level.SEVERE,"BR yedeği okunamadı; korundu.",e);p.kick(Component.text("BR envanter yedeğin okunamadı. Yöneticiye haber ver."));}}
    private void toLobby(Player p){
        reserves.remove(p.getUniqueId());pendingReserve.remove(p.getUniqueId());landingArmor.remove(p.getUniqueId());Session s=sessions.get(p.getUniqueId());if(s==null)return;if(s.room!=null)removeFromRoom(p.getUniqueId(),rooms.get(s.room),false);s.room=null;pages.remove(p.getUniqueId());reset(p);if(!teleport(p,arenas.lobby)){tell(p,"Lobi ışınlanması engellendi; ana lobiye dönülüyor.");leaveGame(p);return;}compass(p);}
    private void leaveGame(Player p){if(hub!=null){hub.returnToLobby(p.getUniqueId());return;}Location l=null;try{l=snapshots.location(p);}catch(IOException ignored){}cleanup(p.getUniqueId());if(l!=null&&l.getWorld()!=null)teleport(p,l);}
    private List<List<UUID>> queuedParties(Room r){Map<UUID,List<UUID>> groups=new LinkedHashMap<>();for(UUID id:r.players){Session s=sessions.get(id);if(s!=null)groups.computeIfAbsent(s.party,k->new ArrayList<>()).add(id);}return new ArrayList<>(groups.values());}
    private int capacity(){return Math.clamp(getConfig().getInt("oyuncu-siniri",20),2,20);}
    private int minimum(Mode mode){return Math.clamp(getConfig().getInt("minimum."+mode.key(),10),mode.size*2,capacity());}
    private int seconds(String key,int defaultValue){return Math.max(1,getConfig().getInt(key,defaultValue));}
    private void queue(Player p,Mode mode){
        ready(p);Session own=sessions.get(p.getUniqueId());if(own==null){joinGame(p);own=sessions.get(p.getUniqueId());if(own==null){Bukkit.getScheduler().runTaskLater(this,()->{if(p.isOnline()&&sessions.containsKey(p.getUniqueId()))try{queue(p,mode);}catch(IllegalArgumentException ex){tell(p,ex.getMessage());}},2);return;}}
        UUID partyId=own.party;List<UUID> group=own.members.stream().filter(id->{Session s=sessions.get(id);return s!=null&&s.party.equals(partyId);}).toList();
        if(group.size()>mode.size)throw new IllegalArgumentException("Grubun "+group.size()+" kişi; "+mode.label+" en fazla "+mode.size+" kişilik grup kabul eder.");
        for(UUID id:group){Session s=sessions.get(id);Player member=Bukkit.getPlayer(id);if(member==null||!auth(member)||s.room!=null||!lobby(member.getLocation()))throw new IllegalArgumentException("Gruptaki herkes BR lobisinde ve boşta olmalı. /br lobi ile bekleme kuyruğundan çık.");}
        Room chosen=null;for(Room r:rooms.values()){ArenaStore.Definition d=definition(r.id);if(!d.ready()||!(r.stage==Stage.BOS||(r.mode==mode&&(r.stage==Stage.BEKLIYOR||r.stage==Stage.GERI_SAYIM)))||r.players.size()+group.size()>capacity())continue;List<List<UUID>> proposed=queuedParties(r);proposed.add(group);if(BattleRules.teams(proposed,mode.size).size()>d.spawns.size())continue;chosen=r;break;}
        if(chosen==null)throw new IllegalArgumentException("Uygun boş arena yok. Üç maç dolu olabilir veya arena kurulumu eksik.");
        chosen.mode=mode;if(chosen.stage==Stage.BOS)chosen.stage=Stage.BEKLIYOR;for(UUID id:group){chosen.players.add(id);sessions.get(id).room=chosen.id;Player member=Bukkit.getPlayer(id);member.closeDialog();pages.remove(id);tell(member,"Arena "+chosen.id+" • "+mode.label+" • "+chosen.players.size()+"/"+capacity()+" oyuncu.");}maybeCountdown(chosen);if(chosen.stage==Stage.GERI_SAYIM&&chosen.players.size()>=capacity())chosen.countdown=Math.min(chosen.countdown,5);
    }
    private void announce(Room r,String text){for(UUID id:new ArrayList<>(r.players)){Player p=Bukkit.getPlayer(id);if(p!=null)tell(p,"Arena "+r.id+" • "+text);}}
    private void maybeCountdown(Room r){if(r.stage==Stage.BEKLIYOR&&r.players.size()>=minimum(r.mode)&&BattleRules.teams(queuedParties(r),r.mode.size).size()>=2){r.countdown=seconds("geri-sayim-saniye",20);r.stage=Stage.GERI_SAYIM;announce(r,"Maç "+r.countdown+" saniye sonra başlayacak.");}}
    private void tick(){for(Room r:rooms.values())try{
        if(r.stage==Stage.BEKLIYOR){maybeCountdown(r);continue;}
        if(r.stage==Stage.GERI_SAYIM){if(r.players.size()<minimum(r.mode)||BattleRules.teams(queuedParties(r),r.mode.size).size()<2){r.stage=Stage.BEKLIYOR;announce(r,"Yeterli oyuncu kalmadı; geri sayım durdu.");}else if(--r.countdown<=0)start(r);else if(r.countdown<=5||r.countdown%10==0)announce(r,"Başlangıca "+r.countdown+" sn.");continue;}
        if(r.stage==Stage.BITIYOR){if(--r.ending<=0)finish(r);continue;}
        if(r.stage!=Stage.OYNANIYOR)continue;r.elapsed++;ArenaStore.Definition d=definition(r.id);double radius=zone(r);
        if(r.elapsed%2==0)for(LootInventory box:r.chests.values())if(box.rare)box.location.getWorld().spawnParticle(Particle.ENCHANT,box.location.clone().add(0.5,1,0.5),6,0.3,0.3,0.3,0.2);
        for(UUID id:new ArrayList<>(r.players)){if(r.stage!=Stage.OYNANIYOR)break;Player p=Bukkit.getPlayer(id);if(p==null){removeFromRoom(id,r,false);continue;}if(p.getGameMode()!=GameMode.SURVIVAL)p.setGameMode(GameMode.SURVIVAL);if(p.getAllowFlight())p.setAllowFlight(false);if(p.isOnGround())p.removePotionEffect(PotionEffectType.SLOW_FALLING);
            if(r.elapsed>=seconds("alan-bekleme-saniye",180)&&BattleRules.outsideZone(p.getX(),p.getZ(),d.center.getX(),d.center.getZ(),radius)){p.damage(Math.max(0.1,getConfig().getDouble("alan-hasari",2)));warn(p,"Daralan alanın dışındasın! Merkeze yaklaş.");}
            presentation.update(p,radius,zone(r,r.elapsed+1),Math.max(0,seconds("alan-bekleme-saniye",180)-r.elapsed),Math.max(0,seconds("alan-bekleme-saniye",180)+seconds("alan-daralma-saniye",600)-r.elapsed));
            p.sendActionBar(Component.text("Arena "+r.id+" • "+r.mode.label+" • Kalan "+r.players.size()+" • Öldürme "+r.kills.getOrDefault(id,0)+" • Alan "+(int)radius+" blok"));
        }
        if(r.stage==Stage.OYNANIYOR&&r.elapsed>=seconds("azami-mac-saniye",1200)){announce(r,"Süre doldu; maç berabere sona erdi.");finish(r);}
    }catch(Exception e){getLogger().log(Level.SEVERE,"Arena "+r.id+" durduruluyor.",e);finish(r);}}
    private double zone(Room r){return zone(r,r.elapsed);}
    private double zone(Room r,int elapsed){ArenaStore.Definition d=definition(r.id);return BattleRules.zone(d.area.radius(d.center.getX(),d.center.getZ()),getConfig().getDouble("son-yaricap",8),elapsed,seconds("alan-bekleme-saniye",180),seconds("alan-daralma-saniye",600));}
    private void start(Room r)throws IOException{
        ArenaStore.Definition d=definition(r.id);if(!d.ready())throw new IllegalArgumentException("Arena kurulumu eksik.");if(!r.chests.isEmpty()||!r.drops.isEmpty())clearWorld(r);List<List<UUID>> teams=BattleRules.teams(queuedParties(r),r.mode.size);if(teams.size()<2)throw new IllegalArgumentException("En az iki rakip takım gerekli.");
        for(Location l:d.spawns)if(!ArenaStore.in(d.area,l)||!ArenaStore.safe(l))throw new IllegalArgumentException("Doğma noktası artık güvenli değil.");
        Area lootArea=BattleRules.lootArea(d.area,d.center.getX(),d.center.getZ(),getConfig().getInt("sandik-dagitim-boyutu",250));
        List<Location> candidates=d.candidates.stream().filter(point->ArenaStore.in(lootArea,point)).toList();
        Set<Integer> outdoors=new HashSet<>();for(int i=0;i<candidates.size();i++)if(ArenaStore.outdoors(candidates.get(i)))outdoors.add(i);
        int multiplier=Math.clamp(getConfig().getInt("sandik-sayisi-carpani",3),1,10),wanted=BattleRules.chestCount(r.players.size(),getConfig().getInt("asgari-sandik",12),getConfig().getDouble("oyuncu-basina-sandik",1.5),multiplier);
        wanted=Math.max(wanted,BattleRules.chestCount(r.players.size(),getConfig().getInt("yogun-ganimet.asgari-sandik",240),getConfig().getDouble("yogun-ganimet.oyuncu-basina-sandik",16),1));
        List<Integer> selected=BattleRules.spacedChests(candidates.stream().map(at->new BattleRules.Point(at.getBlockX(),at.getBlockZ())).toList(),wanted,r.previousChests,outdoors,Math.clamp(getConfig().getInt("sandik-asgari-mesafe",12),8,32),random);
        List<Location> locations=selected.stream().map(candidates::get).toList();r.epoch=UUID.randomUUID();
        arenas.placeChests(locations);int rareCount=Math.max(1,(int)Math.round(locations.size()/(double)multiplier*Math.clamp(getConfig().getDouble("nadir-sandik-orani",0.15),0,1)));
        try{for(int i=0;i<locations.size();i++){Location l=locations.get(i);LootInventory box=new LootInventory(r.id,r.epoch,l,i<rareCount);List<Integer> slots=new ArrayList<>();for(int s=0;s<27;s++)slots.add(s);Collections.shuffle(slots,random);int low=Math.clamp(getConfig().getInt("seyrek-ganimet.min",1),1,20),high=Math.clamp(getConfig().getInt("seyrek-ganimet.max",3),low,24),slot=0;for(ItemStack item:loot.roll(random,box.rare,low+random.nextInt(high-low+1))){tag(item,r);box.inventory.setItem(slots.get(slot++),item);}r.chests.put(ArenaStore.key(l),box);}
            r.previousChests=new HashSet<>(selected);r.teams.clear();r.kills.clear();r.lastHit.clear();r.lastHitAt.clear();r.elapsed=0;r.stage=Stage.OYNANIYOR;List<Location> spawns=new ArrayList<>(d.spawns);Collections.shuffle(spawns,random);var board=presentation.board(r.players.stream().map(Bukkit::getPlayer).filter(Objects::nonNull).toList());
            for(int t=0;t<teams.size();t++)for(UUID id:teams.get(t)){Player p=Bukkit.getPlayer(id);if(p==null)throw new IllegalArgumentException("Oyuncu ayrıldı.");r.teams.put(id,t);reset(p);starterKit(p,r);if(NetworkFeatures.isVip(p)){ReservePool pool=new ReservePool();reserves.put(id,pool);applyReserve(p,pool.add(3));}Location landing=spawns.get(t).clone();landing.setY(Math.min(landing.getWorld().getMaxHeight()-3,landing.getY()+Math.clamp(getConfig().getInt("inis-yuksekligi",60),0,100)));if(!teleport(p,landing))throw new IllegalArgumentException("Maça ışınlanma engellendi.");presentation.enter(p,board,d.center,zone(r));presentation.update(p,zone(r),zone(r),seconds("alan-bekleme-saniye",180),seconds("alan-daralma-saniye",600));p.addPotionEffect(new PotionEffect(PotionEffectType.SLOW_FALLING,1600,0,false,false));p.sendTitle("§6BATTLE ROYALE","§fArena "+r.id+" • "+r.mode.label,5,50,10);}
            announce(r,"Maç başladı! Sandıklar merkez çevresindeki "+(lootArea.maxX()-lootArea.minX()+1)+"×"+(lootArea.maxZ()-lootArea.minZ()+1)+" alanda. Başlangıç: tahta kılıç ve deri zırh.");
        }catch(Exception e){for(Location l:locations)r.chests.putIfAbsent(ArenaStore.key(l),new LootInventory(r.id,r.epoch,l,false));throw e;}
    }
    private void starterKit(Player p,Room r){
        ItemStack sword=new ItemStack(Material.WOODEN_SWORD);var meta=sword.getItemMeta();meta.setDisplayName("§6Başlangıç • Tahta Kılıç");sword.setItemMeta(meta);tag(sword,r);p.getInventory().setItem(0,sword);p.getInventory().setHeldItemSlot(0);
        Material[] types={Material.LEATHER_BOOTS,Material.LEATHER_LEGGINGS,Material.LEATHER_CHESTPLATE,Material.LEATHER_HELMET};String[] names={"Çizme","Pantolon","Göğüslük","Başlık"};ItemStack[] armor=new ItemStack[4];
        for(int i=0;i<armor.length;i++){ItemStack item=new ItemStack(types[i]);var leather=(org.bukkit.inventory.meta.LeatherArmorMeta)item.getItemMeta();leather.setColor(Color.fromRGB(112,77,46));leather.setDisplayName("§6Başlangıç • Deri "+names[i]);item.setItemMeta(leather);tag(item,r);armor[i]=item;}
        p.getInventory().setArmorContents(armor);
    }
    private void tag(ItemStack item,Room r){var meta=item.getItemMeta();meta.getPersistentDataContainer().set(itemKey,PersistentDataType.STRING,r.epoch.toString());item.setItemMeta(meta);}
    private void removeFromRoom(UUID id,Room r,boolean drop){
        if(!r.players.remove(id))return;Player p=Bukkit.getPlayer(id);boolean playing=r.stage==Stage.OYNANIYOR;
        if(drop&&playing&&p!=null){for(ItemStack item:p.getInventory().getContents())if(item!=null&&!item.getType().isAir()&&!marked(item)){Item clone=p.getWorld().dropItem(p.getLocation(),item.clone());r.drops.add(clone.getUniqueId());}}
        Session s=sessions.get(id);if(s!=null)s.room=null;
        if(r.players.isEmpty()){finish(r);return;}
        if(playing){UUID killer=r.lastHit.get(id);if(killer!=null&&System.currentTimeMillis()-r.lastHitAt.getOrDefault(id,0L)<15000&&r.players.contains(killer))r.kills.merge(killer,1,Integer::sum);announce(r,(p==null?"Oyuncu":p.getName())+" elendi • Kalan "+r.players.size());checkWinner(r);}r.teams.remove(id);
    }
    private void checkWinner(Room r){if(r.stage!=Stage.OYNANIYOR)return;Set<Integer> remaining=new HashSet<>();for(UUID id:r.players)remaining.add(r.teams.get(id));if(remaining.size()>1)return;r.stage=Stage.BITIYOR;r.ending=5;for(UUID id:r.players){Player p=Bukkit.getPlayer(id);if(p!=null){p.sendTitle("§6KAZANDIN!","§fArena "+r.id,5,60,10);tell(p,"Takımın hayatta kalan son takım!");}}}
    private void clearWorld(Room r){for(LootInventory box:r.chests.values())for(var viewer:new ArrayList<>(box.inventory.getViewers()))viewer.closeInventory();try{if(arenas!=null)arenas.removeChests(r.chests.values().stream().map(box->box.location).toList());}catch(IOException e){getLogger().log(Level.SEVERE,"Sandık temizliği kaydedilemedi; günlük korundu.",e);}for(UUID id:r.drops){Entity e=Bukkit.getEntity(id);if(e!=null)e.remove();}r.drops.clear();r.chests.clear();}
    private void finish(Room r){r.stage=Stage.BITIYOR;List<UUID> players=new ArrayList<>(r.players);r.players.clear();clearWorld(r);r.teams.clear();r.lastHit.clear();r.lastHitAt.clear();r.kills.clear();r.mode=null;r.elapsed=0;r.stage=Stage.BOS;for(UUID id:players){Session s=sessions.get(id);Player p=Bukkit.getPlayer(id);if(s!=null&&Objects.equals(s.room,r.id)){s.room=null;if(p!=null)toLobby(p);}}}

    private record Button(String label,Runnable action){}
    private void show(Player p,String title,List<String> lines,List<Button> buttons){ready(p);long token=++sequence;pages.put(p.getUniqueId(),token);List<ActionButton> actions=new ArrayList<>();for(Button button:buttons)actions.add(ActionButton.create(tr.kasaba.hub.api.MenuStyle.button(button.label),null,150,DialogAction.customClick((view,audience)->{if(!(audience instanceof Player actor)||!actor.getUniqueId().equals(p.getUniqueId()))return;Bukkit.getScheduler().runTask(this,()->{if(!p.isOnline()||!Objects.equals(pages.get(p.getUniqueId()),token))return;pages.remove(p.getUniqueId());p.closeDialog();try{ready(p);button.action.run();}catch(IllegalArgumentException e){tell(p,e.getMessage());}});},ClickCallback.Options.builder().uses(1).lifetime(Duration.ofMinutes(2)).build())));p.showDialog(Dialog.create(builder->builder.empty().base(DialogBase.builder(tr.kasaba.hub.api.MenuStyle.title(title)).pause(false).canCloseWithEscape(true).body(lines.stream().<DialogBody>map(line->DialogBody.plainMessage(tr.kasaba.hub.api.MenuStyle.line(line),320)).toList()).build()).type(DialogType.multiAction(actions).columns(2).build())));}
    private void menu(Player p){if(!sessions.containsKey(p.getUniqueId())){joinGame(p);return;}Room r=room(p);if(r!=null&&r.stage==Stage.OYNANIYOR){show(p,"Battle Royale",List.of("Arena "+r.id+" • "+r.mode.label+" • Kalan "+r.players.size()),List.of(new Button("Maçtan ayrıl",()->toLobby(p)),new Button("Burada kal",()->{})));return;}List<String> lines=new ArrayList<>();lines.add("Solo tek kişi • İkili 2 kişi • Dörtlü 4 kişi");for(Room room:rooms.values())lines.add(status(room));show(p,"Kasaba • Battle Royale",lines,List.of(new Button("Solo",()->queue(p,Mode.SOLO)),new Button("İkili",()->queue(p,Mode.IKILI)),new Button("Dörtlü",()->queue(p,Mode.DORTLU)),new Button("BR lobisine dön",()->toLobby(p)),new Button("Ana lobiye dön",()->leaveGame(p)),new Button("Burada kal",()->{})));}
    private String status(Room r){return "Arena "+r.id+" • "+(!definition(r.id).ready()?"Kurulum eksik":r.stage.toString().replace('_',' '))+" • "+(r.mode==null?"Mod seçilebilir":r.mode.label)+" • "+r.players.size()+"/"+capacity();}
    private void requireAdmin(Player p){if(!p.hasPermission("br.admin"))throw new IllegalArgumentException("BR yönetim yetkin yok.");}
    private void free(int id){Room r=rooms.get(id);if(r==null)throw new IllegalArgumentException("Arena 1–3 olmalı.");if(r.stage!=Stage.BOS)throw new IllegalArgumentException("Önce /br bitir "+id+" ile bu arenayı boşalt.");}
    private static int number(String[] a,int index,String usage){if(a.length<=index)throw new IllegalArgumentException(usage);try{return Integer.parseInt(a[index]);}catch(NumberFormatException ex){throw new IllegalArgumentException(usage);}}
    private static void need(String[] a,int count,String usage){if(a.length<count)throw new IllegalArgumentException(usage);}
    @Override public boolean onCommand(CommandSender sender,Command cmd,String label,String[] a){
        if(!(sender instanceof Player p)){if(a.length==1&&BattleRules.normalize(a[0]).equals("durum"))rooms.values().forEach(r->tell(sender,status(r)));else tell(sender,"Kurulum komutlarını oyunda /br yardım ile kullan.");return true;}
        try{ready(p);if(a.length==0){menu(p);return true;}String action=BattleRules.normalize(a[0]);switch(action){
            case "yardim"->{tell(p,"/br • /br solo|ikili|dörtlü • /br lobi • /br ayrıl • /br çık • /br durum");if(p.hasPermission("br.admin"))tell(p,"/br lobi ayarla • /br bölge pos1|pos2 • /br bölge kaydet lobi|1|2|3 • /br arena ayarla <1-3> • /br doğma ekle|tara|sil <arena> • /br sandık ekle|tara|sil <arena> • /br ganimet • /br şifa ver • /br yedek ver <2|3> • /br başlat|bitir <arena> • /br düzenleme aç|kapat");}
            case "durum"->rooms.values().forEach(r->tell(p,status(r)));
            case "solo","ikili","dortlu"->queue(p,Mode.parse(action));
            case "katil"->{need(a,2,"/br katıl solo|ikili|dörtlü");queue(p,Mode.parse(a[1]));}
            case "lobi"->{if(a.length>1){requireAdmin(p);if(!BattleRules.normalize(a[1]).equals("ayarla"))throw new IllegalArgumentException("/br lobi ayarla");if(sessions.size()>0)throw new IllegalArgumentException("BR boşken lobi konumu değiştirilebilir.");for(var d:arenas.rooms.values())if(d.area!=null&&!d.area.world().equals(p.getWorld().getUID()))throw new IllegalArgumentException("Lobi ve arenalar aynı dünyada olmalı.");if(!ArenaStore.safe(p.getLocation()))throw new IllegalArgumentException("Lobi için güvenli, düz bir zeminde dur.");Location next=p.getLocation();Area nextArea=arenas.lobbyArea;if(!lobby(next)){nextArea=new Area(p.getWorld().getUID(),next.getBlockX()-24,next.getBlockX()+24,next.getBlockZ()-24,next.getBlockZ()+24);for(var d:arenas.rooms.values())if(d.area!=null&&nextArea.overlaps(d.area))throw new IllegalArgumentException("Lobinin 49×49 koruma alanı arenayla çakışıyor; daha uzakta bir yer seç.");}arenas.lobby=next;arenas.lobbyArea=nextArea;arenas.save();tell(p,"BR lobi konumu ve koruması kaydedildi. /br bölge ile koruma sınırını değiştirebilirsin.");}else if(sessions.containsKey(p.getUniqueId()))toLobby(p);else joinGame(p);}
            case "ayril"->{if(sessions.containsKey(p.getUniqueId()))toLobby(p);else tell(p,"BR'de değilsin.");}
            case "cik"->{if(sessions.containsKey(p.getUniqueId()))leaveGame(p);}
            case "bolge"->regionCommand(p,a);
            case "arena"->{requireAdmin(p);need(a,3,"/br arena ayarla <1-3>");if(!BattleRules.normalize(a[1]).equals("ayarla"))throw new IllegalArgumentException("/br arena ayarla <1-3>");int id=number(a,2,"Arena 1–3 olmalı.");free(id);var d=definition(id);if(!ArenaStore.in(d.area,p.getLocation()))throw new IllegalArgumentException("Önce bu arenanın bölgesini kaydet ve bölgenin içinde dur.");if(d.area.radius(p.getX(),p.getZ())<8)throw new IllegalArgumentException("Merkez arena kenarından en az 10 blok içeride olmalı.");d.center=p.getLocation();arenas.save();tell(p,"Arena "+id+" merkezi kaydedildi.");}
            case "dogma","sandik"->pointCommand(p,a,action.equals("dogma"));
            case "baslat"->{requireAdmin(p);int id=number(a,1,"/br başlat <1-3>");Room r=rooms.get(id);if(r==null||!(r.stage==Stage.BEKLIYOR||r.stage==Stage.GERI_SAYIM))throw new IllegalArgumentException("Bu arenada bekleyen oyuncu yok.");try{start(r);}catch(IOException|RuntimeException ex){finish(r);throw ex;}}
            case "bitir"->{requireAdmin(p);int id=number(a,1,"/br bitir <1-3>");Room r=rooms.get(id);if(r==null)throw new IllegalArgumentException("Arena 1–3 olmalı.");finish(r);tell(p,"Arena "+id+" boşaltıldı; diğer maçlar korundu.");}
            case "duzenleme"->{requireAdmin(p);need(a,2,"/br düzenleme aç|kapat");String mode=BattleRules.normalize(a[1]);if(mode.equals("ac"))editing.add(p.getUniqueId());else if(mode.equals("kapat"))editing.remove(p.getUniqueId());else throw new IllegalArgumentException("/br düzenleme aç|kapat");tell(p,"BR düzenleme: "+(editing.contains(p.getUniqueId())?"Açık (aktif maçlarda geçmez)":"Kapalı"));}
            case "ganimet"->lootCommand(p,a);
            case "yedek"->{requireAdmin(p);need(a,3,"/br yedek ver <2|3> [adet]");if(!BattleRules.normalize(a[1]).equals("ver"))throw new IllegalArgumentException("/br yedek ver <2|3> [adet]");int hearts=number(a,2,"Kalp 2 veya 3 olmalı."),count=a.length>3?number(a,3,"Adet 1–64 olmalı."):1;if(count<1||count>64)throw new IllegalArgumentException("Adet 1–64 olmalı.");if(!p.getInventory().addItem(loot.reserve(hearts,count)).isEmpty())throw new IllegalArgumentException("Envanter dolu.");tell(p,"Yedek kalp yiyeceği verildi; yalnızca aktif BR maçında kullanılır.");}
            case "sifa"->{requireAdmin(p);need(a,2,"/br şifa ver [adet]");if(!BattleRules.normalize(a[1]).equals("ver"))throw new IllegalArgumentException("/br şifa ver [adet]");int count=a.length>2?number(a,2,"Adet 1–64 olmalı."):1;if(count<1||count>64)throw new IllegalArgumentException("Adet 1–64 olmalı.");if(!p.getInventory().addItem(loot.healing(count)).isEmpty())throw new IllegalArgumentException("Envanter dolu.");tell(p,"Şifa Lokması verildi; aktif maçta yiyince anında 2 kalp yeniler.");}
            default->tell(p,"/br yardım");}
        }catch(IllegalArgumentException ex){tell(p,ex.getMessage());}catch(IOException ex){getLogger().log(Level.SEVERE,"BR dosya işlemi başarısız; yedekler korundu.",ex);tell(p,"Dosya kaydedilemedi; yönetici sunucu kayıtlarını kontrol etmeli.");}return true;
    }
    private void regionCommand(Player p,String[] a)throws IOException{requireAdmin(p);need(a,2,"/br bölge pos1|pos2|kaydet <lobi|1|2|3>");String mode=BattleRules.normalize(a[1]);if(mode.equals("pos1")||mode.equals("pos2")){selections.computeIfAbsent(p.getUniqueId(),k->new Location[2])[mode.equals("pos1")?0:1]=p.getLocation();tell(p,"Bölge "+mode+" seçildi (yatay sınır; tüm yükseklikler korunur).");return;}if(!mode.equals("kaydet"))throw new IllegalArgumentException("/br bölge pos1|pos2|kaydet");need(a,3,"/br bölge kaydet lobi|1|2|3");Location[] s=selections.get(p.getUniqueId());if(s==null||s[0]==null||s[1]==null||!s[0].getWorld().equals(s[1].getWorld()))throw new IllegalArgumentException("Önce aynı dünyada pos1 ve pos2 seç.");int id=BattleRules.normalize(a[2]).equals("lobi")?0:number(a,2,"lobi veya 1–3 yaz.");if(id!=0)free(id);else if(!sessions.isEmpty())throw new IllegalArgumentException("BR boşken lobi bölgesi değiştirilebilir.");Area area=new Area(s[0].getWorld().getUID(),Math.min(s[0].getBlockX(),s[1].getBlockX()),Math.max(s[0].getBlockX(),s[1].getBlockX()),Math.min(s[0].getBlockZ(),s[1].getBlockZ()),Math.max(s[0].getBlockZ(),s[1].getBlockZ()));arenas.validateArea(id,area);if(id==0)arenas.lobbyArea=area;else definition(id).area=area;arenas.save();tell(p,(id==0?"Lobi":"Arena "+id)+" bölgesi korumaya alındı.");}
    private void pointCommand(Player p,String[] a,boolean spawn)throws IOException{requireAdmin(p);need(a,3,"/br "+(spawn?"doğma":"sandık")+" ekle|tara|sil|liste <arena> [adet|sıra|tümü]");int id=number(a,2,"Arena 1–3 olmalı.");free(id);var d=definition(id);List<Location> list=spawn?d.spawns:d.candidates;String op=BattleRules.normalize(a[1]);switch(op){
        case "liste"->{for(int i=0;i<list.size();i++){Location l=list.get(i);tell(p,(i+1)+": "+l.getBlockX()+", "+l.getBlockY()+", "+l.getBlockZ());}return;}
        case "ekle"->{Location l=p.getLocation();if(!spawn){Block b=p.getTargetBlockExact(6);if(b==null)throw new IllegalArgumentException("Sandık için bir zemine bak.");l=b.getRelative(0,1,0).getLocation().add(0.5,0,0.5);}if(!ArenaStore.in(d.area,l)||!ArenaStore.safe(l))throw new IllegalArgumentException("Arena içinde, iki blok baş boşluğu olan güvenli zemin seç.");if(d.center==null||Math.hypot(l.getX()-d.center.getX(),l.getZ()-d.center.getZ())>d.area.radius(d.center.getX(),d.center.getZ()))throw new IllegalArgumentException("Nokta başlangıç güvenli alanının dışında.");if(!spawn&&!ArenaStore.in(BattleRules.lootArea(d.area,d.center.getX(),d.center.getZ(),getConfig().getInt("sandik-dagitim-boyutu",250)),l))throw new IllegalArgumentException("Sandık noktası merkezdeki ganimet alanının içinde olmalı (varsayılan 250×250). ");Location point=l.clone();if(list.stream().anyMatch(x->x.distanceSquared(point)<4))throw new IllegalArgumentException("Bu nokta zaten kayıtlı.");list.add(l);}
        case "tara"->{int count=a.length>3?number(a,3,"Adet yaz."):(spawn?20:800);if(count<2||count>1200)throw new IllegalArgumentException("Tarama adedi 2–1200 olmalı.");if(d.area==null||d.center==null)throw new IllegalArgumentException("Önce arena bölgesini ve merkezini ayarla.");List<Location> found=arenas.scan(d,count,random,spawn?d.area:BattleRules.lootArea(d.area,d.center.getX(),d.center.getZ(),getConfig().getInt("sandik-dagitim-boyutu",250)));list.clear();list.addAll(found);}
        case "sil"->{need(a,4,"/br "+(spawn?"doğma":"sandık")+" sil <arena> <sıra|tümü>");if(BattleRules.normalize(a[3]).equals("tumu"))list.clear();else{int index=number(a,3,"Sıra numarası yaz.")-1;if(index<0||index>=list.size())throw new IllegalArgumentException("Kayıt numarası yok.");list.remove(index);}}
        default->throw new IllegalArgumentException("ekle, tara, sil veya liste kullan.");}
        arenas.save();tell(p,"Arena "+id+": "+list.size()+" "+(spawn?"iniş noktası":"sandık adayı")+" kaydedildi. Sandıklar her maçta bu adayların farklı bir kısmında açılır.");}
    private void lootCommand(Player p,String[] a)throws IOException{requireAdmin(p);if(a.length==1||BattleRules.normalize(a[1]).equals("liste")){loot.entries.values().forEach(e->tell(p,e.id()+" • "+e.tier()+" • ağırlık "+e.weight()+" • "+e.min()+"–"+e.max()));tell(p,"Elindeki büyülü eşyayı eklemek: /br ganimet ekle <ad> <ağırlık> <min> <max> <yaygın|nadir|epik|efsane>");return;}String action=BattleRules.normalize(a[1]);if(action.equals("yenile")){loot.load();tell(p,"Ganimet dosyası yenilendi; aktif maç sandıkları değişmedi.");return;}if(action.equals("sil")){need(a,3,"/br ganimet sil <ad>");loot.remove(BattleRules.normalize(a[2]));tell(p,"Ganimet silindi.");return;}if(!action.equals("ekle"))throw new IllegalArgumentException("/br ganimet liste|ekle|sil|yenile");need(a,7,"/br ganimet ekle <ad> <ağırlık> <min> <max> <seviye>");ItemStack item=p.getInventory().getItemInMainHand().clone();if(marked(item))throw new IllegalArgumentException("Menü pusulası ganimet olamaz.");var meta=item.getItemMeta();if(meta!=null){meta.getPersistentDataContainer().remove(itemKey);item.setItemMeta(meta);}try{loot.put(new LootTable.Entry(BattleRules.normalize(a[2]),item,Double.parseDouble(a[3].replace(',','.')),Integer.parseInt(a[4]),Integer.parseInt(a[5]),LootTable.Tier.valueOf(BattleRules.normalize(a[6]).toUpperCase(Locale.ROOT))));}catch(NumberFormatException ex){throw new IllegalArgumentException("Ağırlık ve adetler sayı olmalı.");}tell(p,"Elindeki eşyanın tüm büyüleriyle ganimet kaydedildi.");}
    @Override public List<String> onTabComplete(CommandSender sender,Command cmd,String alias,String[] a){if(a.length==1)return List.of("solo","ikili","dörtlü","lobi","ayrıl","çık","durum","yardım","bölge","arena","doğma","sandık","ganimet","şifa","yedek","başlat","bitir","düzenleme").stream().filter(x->BattleRules.normalize(x).startsWith(BattleRules.normalize(a[0]))).toList();if(a.length==2)return switch(BattleRules.normalize(a[0])){case "bolge"->List.of("pos1","pos2","kaydet");case "arena","lobi"->List.of("ayarla");case "dogma","sandik"->List.of("ekle","tara","sil","liste");case "ganimet"->List.of("liste","ekle","sil","yenile");case "duzenleme"->List.of("aç","kapat");case "sifa","yedek"->List.of("ver");case "baslat","bitir"->List.of("1","2","3");default->List.of();};return List.of();}

    @EventHandler public void join(PlayerJoinEvent e){Bukkit.getScheduler().runTask(this,()->recover(e.getPlayer()));}
    @EventHandler public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();Session s=sessions.get(id);if(s!=null&&s.room!=null)removeFromRoom(id,rooms.get(s.room),true);cleanup(id);selections.remove(id);warnings.remove(id);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void move(PlayerMoveEvent e){if(!e.hasChangedPosition()||moving.contains(e.getPlayer().getUniqueId()))return;if(editing.contains(e.getPlayer().getUniqueId())&&e.getPlayer().hasPermission("br.admin")&&!alive(e.getPlayer()))return;Session s=sessions.get(e.getPlayer().getUniqueId());if(s==null){if(arenas.rooms.values().stream().anyMatch(d->ArenaStore.in(d.area,e.getTo()))){e.setTo(e.getFrom());warn(e.getPlayer(),"Savaş adasına maç başlayınca girilir. /br");}return;}Room r=room(e.getPlayer());boolean permitted=r!=null&&(r.stage==Stage.OYNANIYOR||r.stage==Stage.BITIYOR)?ArenaStore.in(definition(r.id).area,e.getTo()):lobby(e.getTo());if(!permitted){e.setTo(e.getFrom());warn(e.getPlayer(),"BR'den ayrılmak için /br lobi veya /lobi kullan.");}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void travel(PlayerTeleportEvent e){if(moving.contains(e.getPlayer().getUniqueId()))return;Session s=sessions.get(e.getPlayer().getUniqueId());if(s!=null){Room r=room(e.getPlayer());boolean okay=r!=null&&(r.stage==Stage.OYNANIYOR||r.stage==Stage.BITIYOR)?ArenaStore.in(definition(r.id).area,e.getTo()):lobby(e.getTo());if(!okay){e.setCancelled(true);warn(e.getPlayer(),"Önce /br ayrıl veya /lobi kullan.");}}else if(arenas.rooms.values().stream().anyMatch(d->ArenaStore.in(d.area,e.getTo()))&&!editing.contains(e.getPlayer().getUniqueId())){e.setCancelled(true);warn(e.getPlayer(),"Savaş adasına maç başlayınca girilir. /br");}}
    private Player attacker(Entity entity){if(entity instanceof Player p)return p;if(entity instanceof Projectile shot&&shot.getShooter() instanceof Player p)return p;if(entity instanceof TNTPrimed t&&t.getSource() instanceof Player p)return p;return null;}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void damage(EntityDamageEvent e){if(!(e.getEntity() instanceof Player victim))return;Room r=room(victim);if(lobby(victim.getLocation())||(sessions.containsKey(victim.getUniqueId())&&!alive(victim))||(protectedAt(victim.getLocation())&&!alive(victim))){e.setCancelled(true);return;}
        if(e instanceof EntityDamageByEntityEvent hit){Player source=attacker(hit.getDamager());if(source!=null&&(sessions.containsKey(source.getUniqueId())||sessions.containsKey(victim.getUniqueId())||protectedAt(victim.getLocation()))){Room other=room(source);if(r==null||other!=r||!alive(source)||!alive(victim)||Objects.equals(r.teams.get(source.getUniqueId()),r.teams.get(victim.getUniqueId()))){e.setCancelled(true);return;}r.lastHit.put(victim.getUniqueId(),source.getUniqueId());r.lastHitAt.put(victim.getUniqueId(),System.currentTimeMillis());}}
        if(alive(victim)&&e.getFinalDamage()>=victim.getHealth()){e.setCancelled(true);removeFromRoom(victim.getUniqueId(),r,true);toLobby(victim);}}
    @EventHandler(priority=EventPriority.HIGHEST) public void interact(PlayerInteractEvent e){Player p=e.getPlayer();if(marked(e.getItem())){e.setCancelled(true);if(e.getHand()==EquipmentSlot.HAND&&e.getAction().name().startsWith("RIGHT_CLICK")&&auth(p)&&sessions.containsKey(p.getUniqueId()))menu(p);return;}Block b=e.getClickedBlock();if(landingArmor.containsKey(p.getUniqueId())&&e.getItem()!=null&&e.getItem().getType().name().endsWith("_CHESTPLATE"))e.setUseItemInHand(Event.Result.DENY);
        // Empty-hand block clicks can deny item use while still allowing a block action.
        // Handle our authenticated, match-owned virtual chest before the blanket cancellation guard.
        if(b!=null&&b.getType()==Material.CHEST&&e.getAction()==org.bukkit.event.block.Action.RIGHT_CLICK_BLOCK){
            Room current=room(p);LootInventory box=current==null?null:current.chests.get(ArenaStore.key(b.getLocation()));
            if(box!=null){e.setCancelled(true);if(e.getHand()==EquipmentSlot.HAND&&auth(p)&&canLoot(p,box)&&p.getWorld().equals(box.location.getWorld())&&p.getEyeLocation().distanceSquared(box.location.clone().add(0.5,0.5,0.5))<=49)p.openInventory(box.inventory);return;}
        }
        if(e.isCancelled()||b==null)return;Location l=b.getLocation();if(!protectedAt(l)&&!sessions.containsKey(p.getUniqueId()))return;
        if(b.getType()==Material.CHEST&&e.getAction()==org.bukkit.event.block.Action.RIGHT_CLICK_BLOCK){e.setCancelled(true);Room r=room(p);if(alive(p)&&r.chests.containsKey(ArenaStore.key(l))){p.openInventory(r.chests.get(ArenaStore.key(l)).inventory);}else if(edit(p,l)&&!sessions.containsKey(p.getUniqueId()))e.setCancelled(false);return;}
        if(!edit(p,l)&&!(alive(p)&&b.getType().name().endsWith("_DOOR"))){e.setUseInteractedBlock(Event.Result.DENY);ItemStack held=e.getItem();boolean usable=held!=null&&(held.getType().isEdible()||Set.of(Material.BOW,Material.CROSSBOW,Material.SHIELD,Material.TRIDENT).contains(held.getType()));e.setUseItemInHand(alive(p)&&usable?Event.Result.ALLOW:Event.Result.DENY);}}
    private boolean canLoot(Player p,LootInventory inv){Room r=room(p);return alive(p)&&r.id==inv.room&&r.epoch.equals(inv.epoch)&&r.chests.get(ArenaStore.key(inv.location))==inv;}
    @EventHandler(priority=EventPriority.HIGHEST) public void inventory(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(e.getView().getTopInventory().getHolder() instanceof LootInventory inv&&!canLoot(p,inv)){e.setCancelled(true);p.closeInventory();return;}boolean swap=e.getHotbarButton()>=0&&(marked(p.getInventory().getItem(e.getHotbarButton()))||wing(p.getInventory().getItem(e.getHotbarButton())));if(marked(e.getCurrentItem())||marked(e.getCursor())||swap||wing(e.getCurrentItem())||wing(e.getCursor())||e.getClick()==ClickType.SWAP_OFFHAND&&(marked(p.getInventory().getItemInOffHand())||landingArmor.containsKey(p.getUniqueId()))){e.setCancelled(true);return;}if(!alive(p)||NetworkFeatures.isVip(p))return;
        if(e.getClickedInventory()==p.getInventory()&&HotbarInventory.forbidden(e.getSlot())||e.getView().getTopInventory().getType()==InventoryType.CRAFTING&&e.getRawSlot()<5||e.getClick()==ClickType.SWAP_OFFHAND){e.setCancelled(true);return;}
        if(e.isShiftClick()){ItemStack item=e.getCurrentItem();if(item==null||item.getType().isAir())return;if(e.getClickedInventory()!=p.getInventory()||e.getView().getTopInventory().getType()==InventoryType.CRAFTING){e.setCancelled(true);ItemStack moving=item.clone();HotbarInventory.equip(p,moving);int left=moving.getAmount()>0?HotbarInventory.add(p,moving):0;if(left==0)e.setCurrentItem(null);else{moving.setAmount(left);e.setCurrentItem(moving);}}}
    }
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(marked(e.getOldCursor())||wing(e.getOldCursor())||e.getView().getTopInventory().getHolder() instanceof LootInventory inv&&!canLoot(p,inv)){e.setCancelled(true);return;}if(alive(p)&&!NetworkFeatures.isVip(p))for(int raw:e.getRawSlots()){int slot=e.getView().convertSlot(raw);if(e.getView().getInventory(raw)==p.getInventory()&&HotbarInventory.forbidden(slot)||e.getView().getTopInventory().getType()==InventoryType.CRAFTING&&raw<5){e.setCancelled(true);break;}}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void open(InventoryOpenEvent e){if(!(e.getPlayer() instanceof Player p)||!sessions.containsKey(p.getUniqueId()))return;if(e.getInventory().getHolder() instanceof LootInventory inv){if(!canLoot(p,inv))e.setCancelled(true);}else if(e.getInventory().getType()!=InventoryType.CRAFTING&&e.getInventory().getType()!=InventoryType.PLAYER)e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void drop(PlayerDropItemEvent e){Player p=e.getPlayer();if(wing(e.getItemDrop().getItemStack())||marked(e.getItemDrop().getItemStack())||sessions.containsKey(p.getUniqueId())&&!alive(p)){e.setCancelled(true);return;}if(alive(p))room(p).drops.add(e.getItemDrop().getUniqueId());}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void pickup(EntityPickupItemEvent e){if(!(e.getEntity() instanceof Player p))return;ItemStack item=e.getItem().getItemStack();String token=item.hasItemMeta()?item.getItemMeta().getPersistentDataContainer().get(itemKey,PersistentDataType.STRING):null;if(token!=null){Room r=room(p);if(!alive(p)||!r.epoch.toString().equals(token))e.setCancelled(true);else if(!NetworkFeatures.isVip(p)){e.setCancelled(true);int left=HotbarInventory.add(p,item);if(left==0)e.getItem().remove();else item.setAmount(left);}}else if(sessions.containsKey(p.getUniqueId()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void swap(PlayerSwapHandItemsEvent e){if(marked(e.getMainHandItem())||marked(e.getOffHandItem())||alive(e.getPlayer())&&!NetworkFeatures.isVip(e.getPlayer()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void shoot(ProjectileLaunchEvent e){if(!(e.getEntity().getShooter() instanceof Player p)||!sessions.containsKey(p.getUniqueId()))return;if(!alive(p)){e.setCancelled(true);return;}Room r=room(p);e.getEntity().getPersistentDataContainer().set(itemKey,PersistentDataType.STRING,r.epoch.toString());r.drops.add(e.getEntity().getUniqueId());}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void arrow(PlayerPickupArrowEvent e){String token=e.getArrow().getPersistentDataContainer().get(itemKey,PersistentDataType.STRING);if(token!=null&&(!alive(e.getPlayer())||!room(e.getPlayer()).epoch.toString().equals(token)))e.setCancelled(true);else if(alive(e.getPlayer())&&!NetworkFeatures.isVip(e.getPlayer())){e.setCancelled(true);if(HotbarInventory.add(e.getPlayer(),e.getItem().getItemStack())==0){e.getArrow().remove();e.getItem().remove();}}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void decor(EntityDamageEvent e){if(e.getEntity() instanceof Player||!protectedAt(e.getEntity().getLocation()))return;if(e instanceof EntityDamageByEntityEvent hit){Player source=attacker(hit.getDamager());if(source!=null&&edit(source,e.getEntity().getLocation()))return;}e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void entityUse(PlayerInteractEntityEvent e){if(protectedAt(e.getRightClicked().getLocation())&&!edit(e.getPlayer(),e.getRightClicked().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void consume(PlayerItemConsumeEvent e){Player p=e.getPlayer();int hearts=loot.reserveHearts(e.getItem());if(hearts>0){Room r=room(p);ReservePool pool=reserves.computeIfAbsent(p.getUniqueId(),k->new ReservePool());if(!alive(p)||pendingReserve.contains(p.getUniqueId())||!pool.canEat(hearts,p.getAbsorptionAmount(),r==null?System.currentTimeMillis():r.lastHitAt.getOrDefault(p.getUniqueId(),0L),System.currentTimeMillis())){e.setCancelled(true);warn(p,"Darbe aldıktan 3 sn sonra yiyebilirsin. Bir normal + bir güçlü: en fazla 5 sarı kalp; kendi etkisi bitince tekrar yenir.");}return;}if(!loot.isHealing(e.getItem()))return;if(!alive(p)||p.getHealth()>=p.getAttribute(Attribute.MAX_HEALTH).getValue()||System.nanoTime()<heals.getOrDefault(p.getUniqueId(),0L)){e.setCancelled(true);warn(p,"Şifa yalnız maçta, canın eksikken; 10 sn ara ile kullanılır.");}}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void heal(PlayerItemConsumeEvent e){Player p=e.getPlayer();if(!alive(p))return;int hearts=loot.reserveHearts(e.getItem());Room r=room(p);UUID epoch=r.epoch;if(hearts>0){pendingReserve.add(p.getUniqueId());Bukkit.getScheduler().runTask(this,()->{pendingReserve.remove(p.getUniqueId());if(p.isOnline()&&alive(p)&&room(p)==r&&r.epoch.equals(epoch)){ReservePool pool=reserves.computeIfAbsent(p.getUniqueId(),k->new ReservePool());pool.reconcile(p.getAbsorptionAmount());applyReserve(p,pool.add(hearts));}});return;}if(!loot.isHealing(e.getItem()))return;heals.put(p.getUniqueId(),System.nanoTime()+seconds("sifa-bekleme-saniye",10)*1_000_000_000L);Bukkit.getScheduler().runTask(this,()->{if(p.isOnline()&&alive(p)&&room(p)==r&&r.epoch.equals(epoch))p.setHealth(BattleRules.healed(p.getHealth(),p.getAttribute(Attribute.MAX_HEALTH).getValue(),getConfig().getDouble("sifa-kalp",2)));});}
    private void applyReserve(Player p,double amount){p.removePotionEffect(PotionEffectType.ABSORPTION);p.addPotionEffect(new PotionEffect(PotionEffectType.ABSORPTION,PotionEffect.INFINITE_DURATION,2,false,false,true));p.setAbsorptionAmount(Math.min(10,Math.max(0,amount)));}
    private boolean wing(ItemStack item){return item!=null&&item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(wingKey);}
    private void tidyInventories(){for(UUID id:sessions.keySet()){Player p=Bukkit.getPlayer(id);if(p==null||!alive(p)||NetworkFeatures.isVip(p))continue;for(int slot=9;slot<=40;slot++){if(!HotbarInventory.forbidden(slot))continue;ItemStack item=p.getInventory().getItem(slot);if(item==null||item.getType().isAir())continue;p.getInventory().setItem(slot,null);int left=HotbarInventory.add(p,item);if(left>0){item.setAmount(left);Item dropped=p.getWorld().dropItemNaturally(p.getLocation(),item);room(p).drops.add(dropped.getUniqueId());}}}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void naturalHealing(EntityRegainHealthEvent e){if(e.getEntity() instanceof Player p&&alive(p)&&(e.getRegainReason()==EntityRegainHealthEvent.RegainReason.SATIATED||e.getRegainReason()==EntityRegainHealthEvent.RegainReason.REGEN)&&!getConfig().getBoolean("dogal-can-yenileme",false))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void place(BlockPlaceEvent e){if((protectedAt(e.getBlock().getLocation())||sessions.containsKey(e.getPlayer().getUniqueId()))&&!edit(e.getPlayer(),e.getBlock().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void blockBreak(BlockBreakEvent e){if((protectedAt(e.getBlock().getLocation())||sessions.containsKey(e.getPlayer().getUniqueId()))&&!edit(e.getPlayer(),e.getBlock().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void bucket(PlayerBucketEmptyEvent e){if(protectedAt(e.getBlockClicked().getLocation())||sessions.containsKey(e.getPlayer().getUniqueId()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void fill(PlayerBucketFillEvent e){if(protectedAt(e.getBlockClicked().getLocation())||sessions.containsKey(e.getPlayer().getUniqueId()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void explode(EntityExplodeEvent e){e.blockList().removeIf(b->protectedAt(b.getLocation()));}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void blockExplode(BlockExplodeEvent e){e.blockList().removeIf(b->protectedAt(b.getLocation()));}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void burn(BlockBurnEvent e){if(protectedAt(e.getBlock().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void ignite(BlockIgniteEvent e){if(protectedAt(e.getBlock().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void fluid(BlockFromToEvent e){if(protectedAt(e.getBlock().getLocation())||protectedAt(e.getToBlock().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void change(EntityChangeBlockEvent e){if(protectedAt(e.getBlock().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void piston(BlockPistonExtendEvent e){if(protectedAt(e.getBlock().getLocation())||e.getBlocks().stream().anyMatch(b->protectedAt(b.getLocation())||protectedAt(b.getRelative(e.getDirection()).getLocation())))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void retract(BlockPistonRetractEvent e){if(protectedAt(e.getBlock().getLocation())||e.getBlocks().stream().anyMatch(b->protectedAt(b.getLocation())))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void mobs(CreatureSpawnEvent e){if(protectedAt(e.getLocation())&&e.getSpawnReason()!=CreatureSpawnEvent.SpawnReason.CUSTOM)e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void armorStand(PlayerArmorStandManipulateEvent e){if(protectedAt(e.getRightClicked().getLocation())&&!edit(e.getPlayer(),e.getRightClicked().getLocation()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void hanging(org.bukkit.event.hanging.HangingBreakByEntityEvent e){if(protectedAt(e.getEntity().getLocation())&&(!(e.getRemover() instanceof Player p)||!edit(p,e.getEntity().getLocation())))e.setCancelled(true);}
}
